const chatInput = $('Pre-Procesing3').first().json.chatInput.trim();
const sessionId = $('Pre-Procesing3').first().json.sessionId;
const adminPassword = $('Admin Password').first().json.adminPassword;

// Detect command type
const aprender      = chatInput.match(/^\/aprender\s+(\S+)\s+(\S+)\s*:\s*(.+)$/si);
const listar        = /^\/listar-aprendizajes/i.test(chatInput);
const borrar        = chatInput.match(/^\/borrar-aprendizaje\s+(\d+)\s+(\S+)/i);

let commandType = 'NONE';
let payload = {};

if (aprender) {
  const parts = chatInput.match(/^\/aprender\s+(\S+)\s+(\S+)\s*:\s*(.+)$/si);
  commandType = 'APRENDER';
  payload = {
    password:    parts[1].trim(),
    categoria:   parts[2].trim().toUpperCase(),
    instruccion: parts[3].trim()
  };
} else if (listar) {
  const parts = chatInput.match(/^\/listar-aprendizajes\s*(\S+)?/i);
  commandType = 'LISTAR';
  payload = { password: parts && parts[1] ? parts[1].trim() : '' };
} else if (borrar) {
  commandType = 'BORRAR';
  payload = {
    id:       parseInt(borrar[1]),
    password: borrar[2].trim()
  };
}

return [{
  json: {
    chatInput,
    sessionId,
    adminPassword,
    commandType,
    payload,
    isCommand: commandType !== 'NONE'
  }
}];

return [{ json: {
  output: '<div style="font-family:sans-serif;padding:14px 18px;border-left:4px solid #e53e3e;border-radius:6px;background:#fff5f5;font-size:14px;color:#333">'
        + '<strong>&#128274; Clave incorrecta</strong><br>'
        + '<span style="font-size:13px;color:#666">El comando no fue ejecutado.</span>'
        + '</div>',
  type: 'conversation'
}}];

const id = ($input.first().json.id || $input.first().json[0]?.id || '?');
const categoria = $('Detect Command').first().json.payload.categoria;
const instruccion = $('Detect Command').first().json.payload.instruccion;

return [{ json: {
  output: '<div style="font-family:sans-serif;padding:14px 18px;border-left:4px solid #faa819;border-radius:6px;background:#fff8ee;font-size:14px;color:#333">'
        + '<strong>&#9989; Aprendizaje guardado</strong> <span style="font-size:12px;color:#888">#' + id + '</span><br><br>'
        + '<span style="font-size:12px;background:#faa81920;border-radius:4px;padding:2px 8px;color:#7a5800">' + categoria + '</span><br><br>'
        + '<span style="color:#444">' + instruccion + '</span>'
        + '</div>',
  type: 'conversation'
}}];

const rows = $input.all().map(i => i.json);
const GOLD = '#faa819';

if (rows.length === 0 || (rows.length === 1 && Object.keys(rows[0]).length === 0)) {
  return [{ json: {
    output: '<div style="font-family:sans-serif;padding:14px 18px;border-left:4px solid #faa819;border-radius:6px;background:#fff8ee;font-size:14px;color:#333">'
          + '&#128218; No hay aprendizajes guardados aún.</div>',
    type: 'conversation'
  }}];
}

let items = '';
rows.forEach(function(r) {
  const fecha = r.creado_en ? new Date(r.creado_en).toLocaleDateString('es-VE') : '';
  items += '<div style="padding:10px 12px;border:0.5px solid #e8e8e8;border-radius:6px;margin-bottom:6px;background:#fff">'
         + '<div style="display:flex;align-items:center;gap:8px;margin-bottom:4px">'
         + '<span style="font-size:11px;font-weight:600;background:#faa81920;color:#7a5800;padding:2px 8px;border-radius:20px">' + r.categoria + '</span>'
         + '<span style="font-size:11px;color:#aaa;margin-left:auto">#' + r.id + ' · ' + fecha + '</span>'
         + '</div>'
         + '<div style="font-size:13px;color:#444">' + r.instruccion + '</div>'
         + '<div style="font-size:11px;color:#aaa;margin-top:4px">Para borrar: /borrar-aprendizaje ' + r.id + ' [clave]</div>'
         + '</div>';
});

return [{ json: {
  output: '<div style="font-family:sans-serif;max-width:680px">'
        + '<div style="padding:10px 14px;background:#fff8ee;border-left:4px solid ' + GOLD + ';border-radius:6px;margin-bottom:12px;font-size:13px;color:#333">'
        + '&#128218; <strong>' + rows.length + '</strong> aprendizaje(s) activo(s):</div>'
        + items + '</div>',
  type: 'conversation'
}}];

const id = $('Detect Command').first().json.payload.id;
return [{ json: {
  output: '<div style="font-family:sans-serif;padding:14px 18px;border-left:4px solid #faa819;border-radius:6px;background:#fff8ee;font-size:14px;color:#333">'
        + '&#128465; Aprendizaje <strong>#' + id + '</strong> desactivado correctamente.'
        + '</div>',
  type: 'conversation'
}}];

const body = $input.item.json.body || {};
const chatInput = body.chatInput || body.message || '';
const sessionId = body.sessionId || body.session_id || 'no-session-id';
const meta = body.meta || {};
return { json: { chatInput, sessionId, meta, t0: Date.now() } };

const rawOutput = $input.item.json.output || '';

let cleaned = rawOutput
  .replace(/```(?:json)?\s*/gi, '')
  .replace(/```\s*/g, '')
  .trim();

cleaned = cleaned.replace(/"([^"\\]*(?:\\.[^"\\]*)*)"\s*:/g, (match, key) => {
  const cleanKey = key.replace(/[\n\r]/g, '');
  return '"' + cleanKey + '":';
});

// Blindaje: quitar prefijo [INTENT:X] si el modelo deriva de formato
cleaned = cleaned.replace(/^\s*\[[A-Z_]+(?::[A-Z_]+)?\]\s*/, '');
const braceStart = cleaned.indexOf('{');
const braceEnd = cleaned.lastIndexOf('}');
let parsed = null;

if (braceStart !== -1 && braceEnd > braceStart) {
  const jsonCandidate = cleaned.substring(braceStart, braceEnd + 1);
  try {
    parsed = JSON.parse(jsonCandidate);
  } catch(e) {
    const extract = (key) => {
      const r = new RegExp('"' + key + '"\\s*:\\s*"([^"]+)"', 'i');
      const m = jsonCandidate.match(r);
      return m ? m[1].replace(/[\n\r]/g, '').trim() : null;
    };
    const extractBool = (key) => {
      const r = new RegExp('"' + key + '"\\s*:\\s*(true|false)', 'i');
      const m = jsonCandidate.match(r);
      return m ? m[1].toLowerCase() === 'true' : false;
    };
    const tool = extract('tool');
    if (tool) {
      parsed = {
        tool,
        params: {},
        queryIntent: extract('queryIntent') || 'SERVICE',
        isSearchReady: extractBool('isSearchReady'),
        humanSummary: extract('humanSummary') || 'Búsqueda de empresas'
      };
    }
  }
}

const isReady = parsed &&
  (parsed.tool === 'search_empresas' || parsed.tool === 'get_empresa') &&
  parsed.params && typeof parsed.params === 'object' &&
  Object.keys(parsed.params).length > 0 &&
  (parsed.isSearchReady === true || parsed.isSearchReady === 'true');

if (isReady) {
  const queryIntentClean = (parsed.queryIntent || 'SERVICE').replace(/[\n\r]/g, '').trim();
  // Fase MCP-4.10 (16 sep 2026): se mezcla queryIntent DENTRO de params (no como campo hermano)
  // porque asi lo espera el schema de search_empresas en el Worker, y porque un Code node (JS real)
  // es un lugar mucho mas confiable para armar este objeto que la expresion del nodo HTTP de mas
  // abajo (un spread `{...$json.params, queryIntent: $json.queryIntent}` alli resolvia queryIntent
  // como undefined - JSON.stringify lo descartaba en silencio sin ningun error visible).
  // TASK-0013 paso 1 (6 nov 2026): guarda determinista contra la reduccion a una palabra generica.
  // Si el agente mando en "query" UNA sola palabra de contenido y la primera frase de resolvedPhrases
  // (la interpretacion de la frase completa) tiene varias y la contiene, se restituye la frase
  // completa en "query". La palabra suelta no se agrega como frase adicional.
  let queryRestoredFrom = null;
  let queryAccentsStripped = false;
  if (parsed.tool === 'search_empresas' && typeof parsed.params.query === 'string') {
    const norm = (s) => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/\s+/g, ' ').trim();
    const STOP = new Set(['de', 'del', 'la', 'las', 'el', 'los', 'y', 'e', 'o', 'u', 'en', 'para', 'por', 'con', 'a', 'al', 'un', 'una']);
    const content = (s) => norm(s).split(' ').filter((t) => t && !STOP.has(t));
    const phrases = Array.isArray(parsed.params.resolvedPhrases) ? parsed.params.resolvedPhrases : [];
    const full = phrases.find((f) => typeof f === 'string' && f.trim());
    const qWords = content(parsed.params.query);
    // No actua si la frase completa trae relleno de pedido o la ubicacion que ya va en "ciudad":
    // restituirla meteria "empresas" o la ciudad en el texto buscado (bug documentado en el Worker).
    const FILLER = new Set(['empresa', 'empresas', 'necesito', 'busco', 'quiero', 'quien', 'donde', 'dame']);
    const ciudad = norm(parsed.params.ciudad);
    if (full && qWords.length === 1 && !(ciudad && norm(full).includes(ciudad))) {
      const fWords = content(full);
      const stem = (t) => t.replace(/(es|s)$/, '');
      if (fWords.length > 1 && !fWords.some((t) => FILLER.has(t)) && fWords.some((t) => stem(t) === stem(qWords[0]))) {
        queryRestoredFrom = parsed.params.query;
        parsed.params.query = full.trim();
      }
    }
    // "query" va sin tildes: si la frase original las tenia, sigue en resolvedPhrases y el Worker
    // busca las dos variantes (mismo efecto que tenia el flujo anterior, medido en "camion chupon").
    const plain = parsed.params.query.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
    if (plain !== parsed.params.query) {
      const original = parsed.params.query;
      parsed.params.query = plain;
      queryAccentsStripped = true;
      if (!phrases.some((f) => typeof f === 'string' && f.trim() === original.trim())) {
        parsed.params.resolvedPhrases = [...phrases, original];
      }
    }
  }

  const paramsWithIntent = parsed.tool === 'search_empresas'
    ? { ...parsed.params, queryIntent: queryIntentClean, explain: true }
    : parsed.params;

  return {
    json: {
      isSearchReady: 'true',
      needsClarification: 'false',
      tool: parsed.tool,
      params: paramsWithIntent,
      queryIntent: queryIntentClean,
      queryRestoredFrom,
      queryAccentsStripped,
      humanSummary: (parsed.humanSummary || 'Búsqueda de empresas').replace(/[\n\r]/g, '').trim()
    }
  };
}

const conversationalText = cleaned.replace(/\{[\s\S]*\}/, '').trim() || cleaned;
return {
  json: {
    isSearchReady: 'false',
    needsClarification: 'true',
    tool: null,
    params: null,
    queryIntent: 'UNKNOWN',
    humanSummary: null,
    conversationalText: conversationalText || rawOutput.trim()
  }
};

const parse = $('Parse Intent JSON3').first().json;
const intent = String(parse.queryIntent || '').toUpperCase();
const isCompany = (intent === 'COMPANY' || intent === 'RIF');
const chatInput = $('Pre-Procesing3').first().json.chatInput || '';
let term = (parse.humanSummary || chatInput || '').toString()
  .replace(/^dame informaci[o\u00f3]n sobre la empresa\s*/i, '')
  .replace(/^informaci[o\u00f3]n sobre (la empresa )?/i, '')
  .trim();

const GOLD = '#faa819';
const contacto = '<div style="color:#555;margin:10px 0 6px">Para m\u00e1s informaci\u00f3n contacte con la C\u00e1mara Petrolera de Venezuela:</div>'
  + '<div style="display:flex;flex-direction:column;gap:8px;color:#444">'
  + '<div>&#127760; <a href="<URL_REDACTADA>" target="_blank">Sitio Web Oficial de la C\u00e1mara Petrolera</a></div>'
  + '<div>&#128231; <CORREO_REDACTADO></div>'
  + '<div>&#128222; +58 212 7941222</div>'
  + '</div>';

let inner;
if (isCompany && term) {
  inner = '<div style="font-weight:700;font-size:15px;color:#1a1a2e;margin-bottom:10px">&#128269; Empresa no afiliada</div>'
    + '<div style="color:#444;margin-bottom:8px"><strong>' + term + '</strong> no figura actualmente entre las empresas <strong>afiliadas</strong> a la C\u00e1mara Petrolera de Venezuela.</div>'
    + '<div style="color:#666;font-size:13px;margin-bottom:8px">Esto no significa que la empresa no exista, solo que no est\u00e1 en nuestro directorio de afiliados.</div>'
    + '<div style="color:#444">Si representas a esta empresa y deseas afiliarte, escr\u00edbenos a <a href="mailto:<CORREO_REDACTADO>"><CORREO_REDACTADO></a>.</div>'
    + '<div style="color:#999;font-size:12px;margin-top:8px">Registramos tu b\u00fasqueda para mejorar nuestro directorio.</div>';
} else {
  inner = '<div style="font-weight:700;font-size:15px;color:#1a1a2e;margin-bottom:10px">&#128269; No encontramos resultados</div>'
    + '<div style="color:#444;margin-bottom:10px">No encontramos empresas afiliadas que coincidan con su b\u00fasqueda. Intente con otro sector, servicio o ciudad.</div>'
    + contacto;
}

const html = '<div style="font-family:sans-serif;padding:18px 20px;border-left:4px solid ' + GOLD + ';border-radius:6px;background:#fff8ee;line-height:1.8;font-size:14px">'
  + inner + '</div>';

return [{ json: { output: html, type: 'conversation' } }];

// TASK-0013 paso 4 (2026-11-09): declarado primero, coincidencias adicionales marcadas.
// TASK-0029 (2026-11-16): con grupos del Worker, dos secciones (capacidades / experiencias) y selector.
const rows      = $json.rows || [];
const parseNode = $('Parse Intent JSON3').first().json;
const summary   = parseNode.humanSummary || 'Búsqueda de empresas';
const intent    = (parseNode.queryIntent || 'MIXED').toUpperCase();
const count     = rows.length;

const GOLD   = '#faa819';
const GOLDSM = '#faa81920';
const DARK   = 'var(--color-text-primary)';
const TEXT   = 'var(--color-text-secondary)';
const BG     = 'var(--color-background-primary)';
const BGALT  = 'var(--color-background-secondary)';
const BORDER = 'var(--color-border-tertiary)';

// ── Normalización de dirección de país ──────────────────────────────────────────────
function normalizeCountryAddress(value) {
  if (typeof value !== 'string') return value;
  return value.replace(
    /\bVEN\s+Venezuela\s*\(Bolivarian Republic of\)/gi,
    'VEN - Venezuela'
  );
}
// ─────────────────────────────────────────────────────────────────────────

function norm(r) {
  var raw = String(r.website || r.WEBSITE || '').trim();
  var web = raw ? (/^https?:\/\//i.test(raw) ? raw : 'https://' + raw) : '';
  return {
    name:      r.name      || r.NAME      || 'Sin nombre',
    rif:       r.rif       || r.RIF       || '',
    sector:    r.sectores  || r.Sector    || r.SECTOR    || '',
    servicios: r.servicios || r.Servicios || r.SERVICIOS || '',
    ciudad:    r.city_name || r.CIUDAD    || r.ciudad    || '',
    estado:    r.state_name|| r.state     || r.STATE     || '',
    phone:     r.phone     || r.PHONE     || '',
    street:    normalizeCountryAddress(String(r.street || r.STREET || '')),
    website:   web,
    matchType: r.match_type  || null,
    matchedVia: r.matched_via || '',
    explain:   r.explain || null,
    level:     r.match_level || (r.explain && r.explain.nivel) || null,
    id:        r.id != null ? String(r.id) : ''
  };
}

// ── TASK-0013: de dónde sale cada resultado y con qué puntaje ──────────────────
// Los datos vienen del Worker (search_empresas con explain:true): son las mismas contribuciones
// con las que ordenó la lista, no un cálculo aparte.
function esc(s) {
  return String(s == null ? '' : s).replace(/[&<>"']/g, function (ch) {
    return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch];
  });
}
var KIND = {
  coincide:      { icon: '&#10004;', label: 'coincide',      color: '#1a7f37' },
  capacidad_cpv: { icon: '&#9670;',  label: 'capacidad CPV', color: '#0b5cad' },
  similar:       { icon: '&#8776;',  label: 'similar',       color: '#9a6700' },
  relacionado:   { icon: '&#8764;',  label: 'relacionado',   color: '#6e7781' }
};
function kindTag(tipo) {
  var k = KIND[tipo] || KIND.similar;
  return '<span style="color:' + k.color + ';font-weight:600;white-space:nowrap">' + k.icon + ' ' + k.label + '</span>';
}
function sourcesHtml(ex) {
  if (!ex || !ex.fuentes || !ex.fuentes.length) return '';
  var lines = ex.fuentes.map(function (f) {
    var pct = (f.aporte_pct != null) ? ' &middot; ' + Math.round(f.aporte_pct) + '%' : '';
    return '<div style="font-size:11px;color:' + TEXT + ';margin-top:3px;line-height:1.35">'
      + kindTag(f.tipo) + ' &middot; <strong>' + esc(f.fuente) + '</strong>' + pct
      + '<br><span style="opacity:.85">' + esc(f.detalle) + '</span></div>';
  }).join('');
  var calc = '';
  if (ex.puntaje != null) {
    var trs = ex.fuentes.map(function (f) {
      return '<tr><td style="padding:1px 6px 1px 0">' + esc(f.fuente) + '</td><td style="text-align:right;padding:1px 6px">' + f.peso
        + '</td><td style="text-align:right;padding:1px 6px">' + f.posicion_en_fuente + '</td><td style="text-align:right;padding:1px 0 1px 6px">' + f.aporte + '</td></tr>';
    }).join('');
    calc = '<details onclick="event.stopPropagation()" style="margin-top:4px;font-size:11px;color:' + TEXT + '">'
      + '<summary style="cursor:pointer">c&aacute;lculo del puntaje</summary>'
      + '<table style="border-collapse:collapse;margin-top:3px;font-size:11px">'
      + '<tr style="font-weight:600"><td style="padding:1px 6px 1px 0">fuente</td><td style="padding:1px 6px">peso</td><td style="padding:1px 6px">posici&oacute;n</td><td style="padding:1px 0 1px 6px">aporte = peso/(60+pos.)</td></tr>'
      + trs
      + '<tr style="font-weight:600"><td colspan="3" style="padding:2px 6px 0 0">total</td><td style="text-align:right;padding:2px 0 0 6px">' + ex.puntaje + '</td></tr>'
      + '</table></details>';
  }
  return lines + calc;
}
// ── TASK-0013: votos 👍/👎 (los envía window.ciraVote de cira-test; no cambian el ranking) ──
var LOG_ID = $json.search_log_id || null;
function voteBtn(icon, v, title) {
  return '<button type="button" title="' + title + '" onclick="event.stopPropagation();if(window.ciraVote){ciraVote(this,' + v + ')}else{alert(\'Recargue la página para poder votar\')}" '
    + 'style="border:0.5px solid ' + BORDER + ';background:' + BG + ';border-radius:6px;cursor:pointer;padding:1px 6px;font-size:13px;line-height:1.4">' + icon + '</button>';
}
function voteBox(empresaId) {
  if (!LOG_ID) return '';
  return '<span class="cira-vote" data-log="' + LOG_ID + '" data-emp="' + esc(empresaId) + '" onclick="event.stopPropagation()" style="display:inline-flex;gap:4px;align-items:center;margin-left:8px;vertical-align:middle">'
    + voteBtn('&#128077;', 1, 'Este resultado es correcto') + voteBtn('&#128078;', -1, 'Este resultado no corresponde') + '</span>';
}
function resultVote() {
  if (!LOG_ID) return '';
  return '<div class="cira-vote" data-log="' + LOG_ID + '" data-emp="" style="margin-top:10px;padding:8px 12px;font-size:12px;color:' + TEXT + ';background:' + BGALT + ';border-radius:var(--border-radius-md);display:flex;flex-wrap:wrap;gap:6px;align-items:center">'
    + '&iquest;Te sirvi&oacute; esta b&uacute;squeda? ' + voteBtn('&#128077;', 1, 'La búsqueda sirvió') + voteBtn('&#128078;', -1, 'La búsqueda no sirvió')
    + ' &middot; <a href="javascript:void(0)" onclick="event.stopPropagation();if(window.ciraMissing){ciraMissing(this)}" style="color:' + GOLD + '">Falta una empresa</a></div>';
}
function scoreBadge(ex) {
  if (!ex || ex.puntaje_relativo == null) return '';
  return '<span title="Puntaje relativo al primer resultado (= 100)" style="font-size:11px;color:' + TEXT + ';background:' + BGALT
    + ';border-radius:10px;padding:1px 8px;white-space:nowrap;margin-left:6px">puntaje ' + ex.puntaje_relativo + '</span>';
}
function rankingLegend() {
  return '<details style="margin-top:8px;font-size:12px;color:' + TEXT + '"><summary style="cursor:pointer">&iquest;C&oacute;mo se ordenan los resultados?</summary>'
    + '<div style="margin-top:6px;line-height:1.45">Cada fuente arma su propio orden de empresas. Cada empresa suma <strong>peso / (60 + su posici&oacute;n en esa fuente)</strong> '
    + 'por cada fuente en la que aparece. <strong>Primero</strong> aparecen las empresas cuya categor&iacute;a CPV, sector o servicio declarado coincide con lo buscado; '
    + '<strong>despu&eacute;s</strong>, las coincidencias adicionales (experiencias, texto del perfil o servicios parecidos). Cada grupo se ordena por ese total. '
    + 'El <em>puntaje</em> se muestra relativo al primer resultado (= 100), as&iacute; que una coincidencia adicional puede tener m&aacute;s puntaje que una declarada y aun as&iacute; ir despu&eacute;s.'
    + '<table style="border-collapse:collapse;margin-top:6px;font-size:11px">'
    + '<tr style="font-weight:600"><td style="padding:1px 8px 1px 0">fuente</td><td style="padding:1px 8px">tipo</td><td style="padding:1px 8px">grupo</td><td>peso</td></tr>'
    + '<tr><td style="padding:1px 8px 1px 0">Nombre, servicio, sector, certificaci&oacute;n</td><td style="padding:1px 8px">' + kindTag('coincide') + '</td><td style="padding:1px 8px">declarado</td><td>2,5</td></tr>'
    + '<tr><td style="padding:1px 8px 1px 0">Especializaci&oacute;n en el sector buscado</td><td style="padding:1px 8px">' + kindTag('coincide') + '</td><td style="padding:1px 8px">declarado</td><td>2,0</td></tr>'
    + '<tr><td style="padding:1px 8px 1px 0">Experiencia (texto literal)</td><td style="padding:1px 8px">' + kindTag('coincide') + '</td><td style="padding:1px 8px">adicional</td><td>2,5</td></tr>'
    + '<tr><td style="padding:1px 8px 1px 0">Taxonom&iacute;a CPV (texto literal)</td><td style="padding:1px 8px">' + kindTag('coincide') + '</td><td style="padding:1px 8px">declarado</td><td>2,5</td></tr>'
    + '<tr><td style="padding:1px 8px 1px 0">Taxonom&iacute;a CPV (relaci&oacute;n aprobada)</td><td style="padding:1px 8px">' + kindTag('capacidad_cpv') + '</td><td style="padding:1px 8px">declarado</td><td>2,0</td></tr>'
