var bEnd = agentRaw.lastIndexOf('}');
var parse_status;
if (bStart === -1 || bEnd <= bStart) {
  parse_status = 'no_json';
} else {
  var okClean = false;
  try { JSON.parse(agentRaw.substring(bStart, bEnd + 1)); okClean = true; } catch(e) {}
  if (okClean) parse_status = 'ok';
  else if (searchReady) parse_status = 'recovered';
  else parse_status = 'failed';
}
var parse_ok = (parse_status === 'ok' || parse_status === 'no_json');
var error_log_val = (parse_status === 'failed') ? 'json_parse_failed' : null;

// --- inferir resultado_tipo por el camino ejecutado ---
var resultado_tipo;
if (isCommand)          resultado_tipo = wrongPw ? 'comando_error' : 'comando';
else if (!searchReady)  resultado_tipo = 'conversation';
else if (nResultados === 0) resultado_tipo = 'sin_resultados';
else                    resultado_tipo = 'results';

var meta = body.meta || pre.meta || {};
var wp   = meta.wp || {};

var t0 = pre.t0 || null;
var tiempo_respuesta_ms = t0 ? (Date.now() - t0) : null;

var respuesta_ia = agent.output || parse.conversationalText || null;

var output = safe(function(){ return $json.output; }, null)
          || safe(function(){ return $('Format Cards2').first().json.output; }, null)
          || safe(function(){ return $('Code in JavaScript1').first().json.output; }, null)
          || null;

var tokens = 0;
try { tokens = agent.response_metadata.tokenUsage.totalTokens; }
catch(e){ tokens = respuesta_ia ? Math.ceil(String(respuesta_ia).length / 4) : 0; }

var exec = null; try { exec = $execution.id; } catch(e){}

return [{ json: {
  session_id:       pre.sessionId || body.sessionId || 'sin-id',
  pregunta_usuario: pre.chatInput || body.chatInput || '',
  respuesta_ia:     respuesta_ia,
  output:           output,
  tokens_usados:    tokens,
  error_log:        error_log_val,
  metadata: {
    modelo: (() => { try { const m = $('OpenAI Chat Model').params.model; return (m && (m.value || m)) || 'desconocido'; } catch (e) { return 'desconocido'; } })(),
    // --- outcome ---
    resultado_tipo: resultado_tipo,
    parse_status: parse_status,
    parse_ok: parse_ok,
    query_intent: parse.queryIntent || null,
    needs_clarification: (parse.needsClarification === true || parse.needsClarification === 'true'),
    mcp_tool: parse.tool || null,
    mcp_params: parse.params ? JSON.stringify(parse.params) : null,
    resultados_encontrados: isCommand ? null : nResultados,
    tiempo_respuesta_ms: tiempo_respuesta_ms,
    longitud_caracteres: respuesta_ia ? String(respuesta_ia).length : 0,
    ejecucion_id: exec,
    // --- headers crudos (Cloudflare deriva geo/UA) ---
    ip: hdr['x-forwarded-for'] || null,
    user_agent: hdr['user-agent'] || null,
    accept_language: hdr['accept-language'] || null,
    sec_ch_ua_platform: hdr['sec-ch-ua-platform'] || null,
    sec_ch_ua_mobile: hdr['sec-ch-ua-mobile'] || null,
    origin: hdr['origin'] || null,
    referer: hdr['referer'] || null,
    // --- meta del widget ---
    page_url: meta.page_url || null,
    page_title: meta.page_title || null,
    referrer: meta.referrer || null,
    utm_source: meta.utm_source || null,
    utm_medium: meta.utm_medium || null,
    utm_campaign: meta.utm_campaign || null,
    visitor_id: meta.visitor_id || null,
    msg_index: meta.msg_index || null,
    widget_mode: meta.widget_mode || null,
    screen: meta.screen || null,
    viewport: meta.viewport || null,
    timezone: meta.timezone || null,
    connection: meta.connection || null,
    dpr: meta.dpr || null,
    ms_since_load: meta.ms_since_load || null,
    client_ts: meta.client_ts || null,
    ua_hints: meta.ua_hints || null,
    wp_user_id: wp.user_id != null ? wp.user_id : null,
    wp_user_role: wp.user_role || null,
    wp_page_id: wp.page_id != null ? wp.page_id : null
  }
} }];

const raw = $json.data;
const text = typeof raw === 'string' ? raw : JSON.stringify(raw);

// El Worker responde en formato SSE: "event: message\ndata: {...}\n\n"
const match = text.match(/data:\s*(\{[\s\S]*\})/);
let jsonRpc;
try {
  jsonRpc = match ? JSON.parse(match[1]) : JSON.parse(text);
} catch (e) {
  return [{ json: { rows: [], toolError: 'No se pudo parsear la respuesta del MCP: ' + e.message } }];
}

let rows = [];
let toolError = null;

if (jsonRpc.error) {
  toolError = jsonRpc.error.message || 'Error MCP';
} else {
  const contentText = jsonRpc.result && jsonRpc.result.content && jsonRpc.result.content[0] && jsonRpc.result.content[0].text;
  let parsed = [];
  try {
    parsed = contentText ? JSON.parse(contentText) : [];
  } catch (e) {
    toolError = 'Respuesta de la tool no es JSON valido';
  }

  if (Array.isArray(parsed)) {
    rows = parsed;
  } else if (parsed && (parsed.error || parsed.found === false)) {
    toolError = parsed.error || parsed.message || null;
  }
}

return [{ json: { rows, toolError } }];

// TASK-0013: una fila por búsqueda en cira_search_log (vía Worker /search-log).
// TASK-0029: cada resultado guarda también su grupo (capacidad / experiencia) y la capacidad que coincidió;
// engine_version lleva la revisión de este flujo y el Worker le agrega su versión desplegada.
const FLOW_REVISION = 'T29-B r1';
const u = $input.first().json;
const pre = $('Pre-Procesing3').first().json;
const p = $('Parse Intent JSON3').first().json;
const bsp = $('Build System Prompt').first().json;
const rows = u.rows || [];
const evidence = rows.map(function (r, i) {
  var ex = r.explain;
  var cap = r.capacidad;
  return {
    id: Number(r.id), pos: i + 1,
    grupo: r.grupo || null,
    cap: cap ? { tipo: cap.tipo, codigo: cap.codigo || null, origen: cap.origen || null, coincidencia: cap.coincidencia || null } : null,
    nexp: Array.isArray(r.experiencias_relacionadas) ? r.experiencias_relacionadas.length : null,
    puntaje: ex ? ex.puntaje : null, rel: ex ? ex.puntaje_relativo : null,
    fuentes: ex && ex.fuentes ? ex.fuentes.map(function (f) { return { lista: f.lista, tipo: f.tipo, aporte: f.aporte, pct: f.aporte_pct }; }) : null,
    via: r.matched_via || null
  };
});
return [{ json: {
  source: 'n8n_chat',
  session_ref: pre.sessionId,
  n8n_execution_id: String($execution.id),
  user_input: String(pre.chatInput || '').slice(0, 2000) || '(vacio)',
  agent_tool: p.tool,
  agent_params: p.params,
  result_empresa_ids: rows.map(function (r) { return Number(r.id); }),
  result_evidence: evidence,
  engine_version: 'flow ' + $workflow.id + ' ' + (bsp.promptVersion || '') + ' | ' + FLOW_REVISION,
  response_ms: Math.max(0, Date.now() - (pre.t0 || Date.now())),
  error: u.toolError || null
} }];

// TASK-0013: si el registro falla, la búsqueda sigue igual, solo que sin botones de voto.
const u = $('Unwrap MCP Result').first().json;
const r = $input.first().json || {};
return [{ json: Object.assign({}, u, { search_log_id: (r && r.ok && r.id) ? r.id : null }) }];
